import java.util.Scanner;

public class Main {
    static final int MOD_CONST = 1000000007;
    static int current_mod = MOD_CONST;
    static int[] P = new int[1000001];

    static int add_mod(int a, int b) {
        int res = a + b;
        return res < current_mod ? res : res - current_mod;
    }

    static int multiply_mod(int a, int b) {
        long res = (long) a * b;
        return (int) (res % current_mod);
    }

    static int fast_power(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply_mod(res, base);
            }
            base = multiply_mod(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int find_beb(int a, int m) {
        for (int i = 0; i < P.length; i++) {
            P[i] = -1;
        }
        int s = (int) Math.sqrt(m);
        current_mod = m;
        int r = a % m;
        int d = fast_power(a, m - 2);
        for (int i = 0; i <= s; ++i) {
            if (P[r] == -1) P[r] = i;
            r = multiply_mod(r, d);
            if (r == 1) {
                current_mod = MOD_CONST;
                return i + 1;
            }
        }
        d = fast_power(a, s);
        r = d;
        for (int i = 1; i <= s; ++i) {
            if (P[r] > -1) {
                current_mod = MOD_CONST;
                return s * i + P[r];
            }
            r = multiply_mod(r, d);
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 1) {
            System.out.println(fast_power(p, p));
        } else if (k == 0) {
            System.out.println(fast_power(p, p - 1));
        } else {
            int b = find_beb(k, p);
            System.out.println(fast_power(p, (p - 1) / b));
        }
        sc.close();
    }
}
